import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { RepairScene, type FaultKind } from './scene';
import { directRepairStory } from './director';

let scene: RepairScene | null = null;
let root: HTMLElement | null = null;
let currentFault: FaultKind = 'stalled';
let removeListeners: Array<() => void> = [];

const faultCopy: Record<FaultKind, { part: string; order: string; safety: string; difficulty: string }> = {
  stalled: {
    part: '启动电容与轴套',
    order: '先断电并拨动扇叶，再检查轴套阻力，最后测量启动电容。',
    safety: '电容可能存有余电；拆线前先由志愿者确认放电。',
    difficulty: '预计难度：中等 · 约 35 分钟'
  },
  noise: {
    part: '护网、扇叶与轴套',
    order: '先查护网松动，再检查扇叶偏摆，最后清洁并评估轴套。',
    safety: '任何通电测试都必须装回护网，并保持工具离开旋转面。',
    difficulty: '预计难度：入门 · 约 25 分钟'
  },
  weak: {
    part: '扇叶积尘与电机绕组',
    order: '先清洁风道和扇叶，再检查转速档位，最后测量绕组状态。',
    safety: '清洁前拔掉插头；不要向电机内部直接喷洒清洁剂。',
    difficulty: '预计难度：中等 · 约 40 分钟'
  }
};

function markup(): string {
  return `
    <main class="repair-story" aria-label="社区维修工作坊电风扇诊断">
      <header class="workshop-header">
        <a class="workshop-mark" href="#diagnosis" aria-label="回到诊断台">
          <span aria-hidden="true">修</span>
          <strong>街坊维修间</strong>
        </a>
        <p>周六开放 · 工具与志愿者在桌边等你</p>
      </header>

      <section class="hero" id="diagnosis">
        <div class="hero-copy">
          <p class="eyebrow">老式台式风扇 · 诊断卡 08</p>
          <h1>先听它怎么说，<br>再决定拆哪里。</h1>
          <p class="intro">选择最接近的症状。装配图会标出可能的故障部件，并给出一条安全、可执行的检查顺序。</p>
          <div class="fault-picker" role="group" aria-label="选择风扇症状">
            <button type="button" data-fault="stalled" aria-pressed="true"><span>01</span>不转</button>
            <button type="button" data-fault="noise" aria-pressed="false"><span>02</span>异响</button>
            <button type="button" data-fault="weak" aria-pressed="false"><span>03</span>风力变弱</button>
          </div>
        </div>

        <aside class="diagnostic-card" aria-live="polite">
          <p class="card-label">当前检查对象</p>
          <h2 data-field="part">启动电容与轴套</h2>
          <ol class="stage-rail" aria-label="维修阶段">
            <li data-stage="0" class="is-active"><b>诊断</b><span>观察与手动检查</span></li>
            <li data-stage="1"><b>拆解</b><span>按顺序展开部件</span></li>
            <li data-stage="2"><b>测试</b><span>确认结果再复装</span></li>
          </ol>
          <p class="check-order" data-field="order">先断电并拨动扇叶，再检查轴套阻力，最后测量启动电容。</p>
          <p class="safety"><strong>安全提示</strong><span data-field="safety">电容可能存有余电；拆线前先由志愿者确认放电。</span></p>
          <p class="difficulty" data-field="difficulty">预计难度：中等 · 约 35 分钟</p>
        </aside>
      </section>

      <section class="process-note" aria-label="维修流程说明">
        <p class="note-number">桌面流程 / 01—03</p>
        <div>
          <h2>从判断，到拆开，再到有把握地装回去。</h2>
          <p>向下滚动查看同一台风扇的三个工作状态。图中彩色部件保持原位关系，只有当前需要理解的结构会展开。</p>
        </div>
      </section>

      <section class="booking" id="booking">
        <div>
          <p class="eyebrow">带上你的风扇，也带上它最近的声音</p>
          <h2>给旧东西一张<br>认真检查的桌子。</h2>
        </div>
        <div class="booking-action">
          <p>每张桌提供万用表、常用工具、护目镜和一位社区志愿者。零经验也可以来。</p>
          <a href="#booking" data-book>预约一张维修桌 <span aria-hidden="true">→</span></a>
          <small>周六 10:00—17:00 · 每桌 60 分钟</small>
        </div>
      </section>
    </main>`;
}

function updateCopy(fault: FaultKind): void {
  if (!root) return;
  const copy = faultCopy[fault];
  (root.querySelector('[data-field="part"]') as HTMLElement | null)?.replaceChildren(copy.part);
  (root.querySelector('[data-field="order"]') as HTMLElement | null)?.replaceChildren(copy.order);
  (root.querySelector('[data-field="safety"]') as HTMLElement | null)?.replaceChildren(copy.safety);
  (root.querySelector('[data-field="difficulty"]') as HTMLElement | null)?.replaceChildren(copy.difficulty);
}

startExperience(defineExperience({
  mount(context) {
    root = context.container.ownerDocument.createElement('div');
    root.className = 'repair-page';
    root.innerHTML = markup();
    context.container.appendChild(root);

    try {
      scene = new RepairScene(context.canvas, context.viewport, context.quality === 'low');
    } catch {
      scene = null;
      root.classList.add('webgl-unavailable');
    }

    const buttons = Array.from(root.querySelectorAll<HTMLButtonElement>('[data-fault]'));
    buttons.forEach((button) => {
      const handler = (): void => {
        const next = button.dataset.fault;
        if (next !== 'stalled' && next !== 'noise' && next !== 'weak') return;
        currentFault = next;
        buttons.forEach((item) => item.setAttribute('aria-pressed', String(item === button)));
        updateCopy(next);
        scene?.setFault(next);
      };
      button.addEventListener('click', handler);
      removeListeners.push(() => button.removeEventListener('click', handler));
    });

    const booking = root.querySelector<HTMLAnchorElement>('[data-book]');
    if (booking) {
      const handler = (event: MouseEvent): void => {
        event.preventDefault();
        booking.textContent = '已为你保留预约入口 ✓';
        booking.setAttribute('aria-label', '预约入口已准备，请在工作坊开放时登记');
      };
      booking.addEventListener('click', handler);
      removeListeners.push(() => booking.removeEventListener('click', handler));
    }
  },

  update(frame) {
    if (!root) return;
    const state = directRepairStory(frame.progress, frame.pointer, frame.elapsed, frame.reducedMotion);
    root.style.setProperty('--story-progress', state.progress.toFixed(3));
    root.style.setProperty('--stage-shift', `${state.stageShift.toFixed(2)}%`);
    const stages = Array.from(root.querySelectorAll<HTMLElement>('[data-stage]'));
    stages.forEach((item, index) => item.classList.toggle('is-active', index === state.stage));
    scene?.render(state, currentFault, frame.delta);
  },

  resize(viewport) {
    scene?.resize(viewport);
  },

  dispose() {
    removeListeners.forEach((remove) => remove());
    removeListeners = [];
    scene?.dispose();
    scene = null;
    root?.remove();
    root = null;
  }
}));

export interface StoryPointer {
  x: number;
  y: number;
}

export interface RepairStoryState {
  progress: number;
  stage: 0 | 1 | 2;
  stageShift: number;
  explode: number;
  testPulse: number;
  finalLock: number;
  cameraX: number;
  cameraY: number;
  cameraZ: number;
  lookX: number;
  lookY: number;
}

function clamp01(value: number): number {
  return Math.max(0, Math.min(1, value));
}

function smoothstep(edge0: number, edge1: number, value: number): number {
  const t = clamp01((value - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
}

export function directRepairStory(
  rawProgress: number,
  pointer: StoryPointer,
  elapsed: number,
  reducedMotion: boolean
): RepairStoryState {
  const progress = clamp01(rawProgress);
  const stage: 0 | 1 | 2 = progress < 0.34 ? 0 : progress < 0.76 ? 1 : 2;
  const effective = reducedMotion ? (stage === 0 ? 0.12 : stage === 1 ? 0.58 : 1) : progress;

  // The assembly opens only for the inspection beat, then returns to a readable tested whole.
  const opening = smoothstep(0.25, 0.52, effective);
  const closing = smoothstep(0.72, 0.94, effective);
  const explode = opening * (1 - closing);
  const finalLock = smoothstep(0.82, 0.98, effective);
  const pulseClock = reducedMotion ? 0 : elapsed;
  const testPulse = stage === 2 && finalLock < 0.92 ? 0.5 + Math.sin(pulseClock * 3.2) * 0.5 : finalLock;
  const pointerWeight = reducedMotion ? 0 : 0.16 * (1 - finalLock);

  return {
    progress: effective,
    stage,
    stageShift: stage * -33.333,
    explode,
    testPulse,
    finalLock,
    cameraX: 0.25 + pointer.x * pointerWeight,
    cameraY: 0.3 - pointer.y * pointerWeight * 0.55,
    cameraZ: 8.3 - opening * 0.35 + finalLock * 0.22,
    lookX: 0.15 + pointer.x * pointerWeight * 0.22,
    lookY: 0.25 - pointer.y * pointerWeight * 0.12
  };
}

import * as THREE from 'three';
import type { RepairStoryState } from './director';

export type FaultKind = 'stalled' | 'noise' | 'weak';

interface ViewportLike {
  width: number;
  height: number;
  dpr: number;
}

interface PartRecord {
  object: THREE.Object3D;
  homeX: number;
  explodeX: number;
}

export class RepairScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.PerspectiveCamera(32, 1, 0.1, 50);
  private readonly assembly = new THREE.Group();
  private readonly bladeHub = new THREE.Group();
  private readonly parts: PartRecord[] = [];
  private readonly geometries = new Set<THREE.BufferGeometry>();
  private readonly materials = new Set<THREE.Material>();
  private readonly faultMaterials: Record<FaultKind, THREE.MeshStandardMaterial[]>;
  private readonly accent = new THREE.Color('#e9563f');
  private readonly neutral = new THREE.Color('#315a6b');
  private readonly lowQuality: boolean;

  constructor(canvas: HTMLCanvasElement, viewport: ViewportLike, lowQuality: boolean) {
    this.lowQuality = lowQuality;
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: !lowQuality, alpha: true, powerPreference: 'high-performance' });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.setClearColor(0x000000, 0);
    this.scene.fog = new THREE.Fog('#f4efd9', 10, 18);

    const blue = this.material('#315a6b', 0.72);
    const red = this.material('#e9563f', 0.62);
    const yellow = this.material('#e8b83f', 0.58);
    const mint = this.material('#83b99b', 0.65);
    const cream = this.material('#f4efd9', 0.78);
    const dark = this.material('#173743', 0.78);

    this.faultMaterials = { stalled: [yellow, dark], noise: [red, blue], weak: [mint, red] };

    this.buildFan({ blue, red, yellow, mint, cream, dark });
    this.scene.add(this.assembly);

    const key = new THREE.DirectionalLight('#fff6d5', 3.1);
    key.position.set(-4, 6, 7);
    this.scene.add(key);
    const fill = new THREE.DirectionalLight('#8fc3ca', 1.3);
    fill.position.set(5, 1, 4);
    this.scene.add(fill);
    this.scene.add(new THREE.HemisphereLight('#fff9e8', '#8aa19a', 1.55));

    this.camera.position.set(0.25, 0.3, 8.3);
    this.resize(viewport);
  }

  private material(color: string, roughness: number): THREE.MeshStandardMaterial {
    const material = new THREE.MeshStandardMaterial({ color, roughness, metalness: 0.12 });
    this.materials.add(material);
    return material;
  }

  private mesh(geometry: THREE.BufferGeometry, material: THREE.Material): THREE.Mesh {
    this.geometries.add(geometry);
    return new THREE.Mesh(geometry, material);
  }

  private addPart(object: THREE.Object3D, homeX: number, explodeX: number): void {
    object.position.x = homeX;
    this.parts.push({ object, homeX, explodeX });
    this.assembly.add(object);
  }

  private buildFan(m: Record<'blue' | 'red' | 'yellow' | 'mint' | 'cream' | 'dark', THREE.MeshStandardMaterial>): void {
    const base = this.mesh(new THREE.CylinderGeometry(1.3, 1.5, 0.28, 40), m.blue);
    base.scale.z = 0.62;
    base.position.set(0, -2.35, 0);
    this.assembly.add(base);

    const neck = this.mesh(new THREE.CylinderGeometry(0.17, 0.23, 1.55, 20), m.red);
    neck.position.set(0, -1.48, 0);
    this.assembly.add(neck);

    const pivot = this.mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.42, 24), m.yellow);
    pivot.rotation.x = Math.PI / 2;
    pivot.position.set(0, -0.65, 0);
    this.assembly.add(pivot);

    const rear = new THREE.Group();
    const motor = this.mesh(new THREE.CylinderGeometry(0.68, 0.78, 1.05, 32), m.dark);
    motor.rotation.x = Math.PI / 2;
    rear.add(motor);
    const vent = this.mesh(new THREE.TorusGeometry(0.47, 0.055, 10, 32), m.mint);
    vent.position.z = -0.56;
    rear.add(vent);
    rear.position.y = 0.55;
    this.addPart(rear, 0, -2.0);

    const rearCage = this.makeCage(m.blue);
    rearCage.position.y = 0.55;
    this.addPart(rearCage, 0, -1.0);

    const blades = this.bladeHub;
    const hub = this.mesh(new THREE.SphereGeometry(0.34, 24, 16), m.yellow);
    blades.add(hub);
    for (let i = 0; i < 4; i += 1) {
      const blade = this.mesh(new THREE.CapsuleGeometry(0.3, 1.05, 8, 16), m.mint);
      blade.scale.set(0.72, 1, 0.16);
      blade.position.y = 0.78;
      blade.rotation.z = -0.32;
      const carrier = new THREE.Group();
      carrier.rotation.z = i * Math.PI * 0.5;
      carrier.add(blade);
      blades.add(carrier);
    }
    blades.position.y = 0.55;
    blades.position.z = 0.18;
    this.addPart(blades, 0, 0.3);

    const frontCage = this.makeCage(m.red);
    frontCage.position.y = 0.55;
    frontCage.position.z = 0.47;
    this.addPart(frontCage, 0, 1.55);

    const badge = this.mesh(new THREE.CylinderGeometry(0.43, 0.43, 0.1, 28), m.cream);
    badge.rotation.x = Math.PI / 2;
    badge.position.set(0, 0.55, 0.77);
    this.addPart(badge, 0, 2.3);

    this.assembly.rotation.y = -0.1;
    this.assembly.position.x = 1.15;
  }

  private makeCage(material: THREE.Material): THREE.Group {
    const cage = new THREE.Group();
    [0.78, 1.28, 1.72].forEach((radius) => {
      const ring = this.mesh(new THREE.TorusGeometry(radius, 0.026, 7, this.lowQuality ? 36 : 64), material);
      cage.add(ring);
    });
    for (let i = 0; i < 12; i += 1) {
      const spoke = this.mesh(new THREE.BoxGeometry(0.028, 1.72, 0.025), material);
      spoke.position.y = 0.86;
      spoke.rotation.z = i * Math.PI / 6;
      cage.add(spoke);
    }
    return cage;
  }

  setFault(fault: FaultKind): void {
    const active = new Set<THREE.Material>(this.faultMaterials[fault]);
    this.materials.forEach((material) => {
      if (material instanceof THREE.MeshStandardMaterial) {
        material.emissive.copy(active.has(material) ? this.accent : new THREE.Color(0x000000));
        material.emissiveIntensity = active.has(material) ? 0.18 : 0;
      }
    });
  }

  render(state: RepairStoryState, fault: FaultKind, delta: number): void {
    this.parts.forEach((part, index) => {
      const stagger = Math.max(0, Math.min(1, state.explode * 1.35 - index * 0.07));
      const eased = stagger * stagger * (3 - 2 * stagger);
      part.object.position.x = THREE.MathUtils.lerp(part.homeX, part.explodeX, eased);
    });

    const testedSpeed = state.stage === 2 ? (0.35 + state.testPulse * 0.35) : 0;
    this.bladeHub.rotation.z -= Math.min(delta, 0.05) * testedSpeed;
    this.assembly.rotation.y = THREE.MathUtils.lerp(-0.1, -0.035, state.finalLock);
    this.assembly.position.x = THREE.MathUtils.lerp(1.15, 0.85, state.finalLock);

    this.camera.position.set(state.cameraX, state.cameraY, state.cameraZ);
    this.camera.lookAt(state.lookX, state.lookY, 0);

    const selected = new Set<THREE.Material>(this.faultMaterials[fault]);
    this.assembly.traverse((object) => {
      if (!(object instanceof THREE.Mesh)) return;
      const meshMaterials = Array.isArray(object.material) ? object.material : [object.material];
      meshMaterials.forEach((material) => {
        if (material instanceof THREE.MeshStandardMaterial) {
          const emphasis = selected.has(material) ? 0.2 + state.testPulse * 0.18 : 0;
          material.emissive.copy(selected.has(material) ? this.accent : this.neutral);
          material.emissiveIntensity = emphasis;
        }
      });
    });

    this.renderer.render(this.scene, this.camera);
  }

  resize(viewport: ViewportLike): void {
    const width = Math.max(1, viewport.width);
    const height = Math.max(1, viewport.height);
    this.renderer.setPixelRatio(Math.min(viewport.dpr, this.lowQuality ? 1.25 : 2));
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  dispose(): void {
    this.geometries.forEach((geometry) => geometry.dispose());
    this.materials.forEach((material) => material.dispose());
    this.renderer.dispose();
  }
}

@import url('');

:root {
  color-scheme: light;
  --ink: #173743;
  --paper: #f6f0d9;
  --paper-light: #fffaf0;
  --red: #e9563f;
  --blue: #315a6b;
  --yellow: #e8b83f;
  --mint: #83b99b;
  --line: rgba(23, 55, 67, 0.24);
}

*, *::before, *::after { box-sizing: border-box; }
html { margin: 0; max-width: 100%; scroll-behavior: smooth; overflow-x: clip; }
body { margin: 0; max-width: 100%; overflow-x: clip; background: var(--paper); color: var(--ink); }
button, a { font: inherit; }

.repair-page {
  min-height: 220vh;
  max-width: 100%;
  font-family: "Arial Narrow", "Noto Sans SC", "Microsoft YaHei", sans-serif;
  background:
    linear-gradient(rgba(23,55,67,.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(23,55,67,.055) 1px, transparent 1px),
    var(--paper);
  background-size: 32px 32px;
}

.repair-page canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.repair-story { position: relative; z-index: 2; min-height: 220vh; max-width: 100%; }
.workshop-header {
  min-height: 66px;
  padding: 12px clamp(18px, 4vw, 64px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
  background: rgba(246,240,217,.88);
}
.workshop-header p { margin: 0; font-size: 12px; letter-spacing: .08em; }
.workshop-mark { display: inline-flex; align-items: center; gap: 10px; color: inherit; text-decoration: none; }
.workshop-mark span { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; color: var(--paper-light); background: var(--red); font-weight: 800; }
.workshop-mark strong { font-size: 14px; letter-spacing: .12em; }

.hero {
  min-height: calc(100vh - 66px);
  padding: clamp(30px, 7vh, 76px) clamp(18px, 4vw, 64px) 36px;
  display: grid;
  grid-template-columns: minmax(280px, .84fr) minmax(600px, 1.55fr);
  gap: clamp(28px, 6vw, 92px);
  align-items: start;
}
.hero-copy { max-width: 570px; padding-top: 2vh; }
.eyebrow, .card-label, .note-number { margin: 0 0 18px; color: var(--red); font-weight: 800; font-size: 11px; letter-spacing: .16em; text-transform: uppercase; }
h1 {
  max-width: 13ch;
  margin: 0;
  font-family: Georgia, "Songti SC", serif;
  font-size: clamp(42px, 6.1vw, 86px);
  line-height: .98;
  letter-spacing: -.055em;
  font-weight: 600;
}
.intro { max-width: 45ch; margin: 25px 0 24px; font-size: clamp(15px, 1.35vw, 18px); line-height: 1.75; }
.fault-picker { display: flex; flex-wrap: wrap; gap: 9px; }
.fault-picker button {
  min-height: 48px;
  padding: 10px 16px;
  border: 1px solid var(--ink);
  border-radius: 2px;
  color: var(--ink);
  background: var(--paper-light);
  cursor: pointer;
  font-weight: 700;
}
.fault-picker button span { margin-right: 8px; color: var(--red); font-size: 10px; }
.fault-picker button[aria-pressed="true"] { color: var(--paper-light); background: var(--blue); box-shadow: 4px 4px 0 var(--yellow); transform: translate(-2px, -2px); }
.fault-picker button:focus-visible, .booking a:focus-visible { outline: 3px solid var(--yellow); outline-offset: 3px; }

.diagnostic-card {
  align-self: end;
  width: min(430px, 42vw);
  margin: min(42vh, 370px) 0 0 auto;
  padding: 20px;
  border: 1px solid var(--ink);
  background: rgba(255,250,240,.93);
  box-shadow: 7px 7px 0 rgba(49,90,107,.18);
}
.diagnostic-card h2 { margin: 0 0 16px; font-family: Georgia, "Songti SC", serif; font-size: clamp(25px, 2.3vw, 36px); font-weight: 600; }
.stage-rail { margin: 0 -20px; padding: 0; display: grid; grid-template-columns: repeat(3, 1fr); border-block: 1px solid var(--line); list-style: none; }
.stage-rail li { min-width: 0; padding: 12px 9px; border-right: 1px solid var(--line); opacity: .44; }
.stage-rail li:last-child { border-right: 0; }
.stage-rail li.is-active { opacity: 1; background: rgba(232,184,63,.22); }
.stage-rail b, .stage-rail span { display: block; }
.stage-rail b { font-size: 13px; }
.stage-rail span { margin-top: 3px; font-size: 9px; line-height: 1.35; }
.check-order { margin: 17px 0; min-height: 3.2em; font-size: 14px; line-height: 1.65; }
.safety { display: grid; grid-template-columns: 72px 1fr; gap: 9px; margin: 0; padding: 11px; background: var(--yellow); font-size: 11px; line-height: 1.55; }
.difficulty { margin: 13px 0 0; color: var(--blue); font-size: 11px; font-weight: 800; }

.process-note {
  min-height: 74vh;
  padding: 15vh clamp(18px, 4vw, 64px) 14vh;
  display: grid;
  grid-template-columns: minmax(160px, .6fr) minmax(300px, 1fr) minmax(360px, .8fr);
  gap: 28px;
  align-items: start;
  border-top: 1px solid var(--line);
}
.process-note > div { grid-column: 2; max-width: 590px; padding: 26px; border-left: 8px solid var(--mint); background: rgba(255,250,240,.84); }
.process-note h2 { margin: 0; font-family: Georgia, "Songti SC", serif; font-size: clamp(30px, 4vw, 58px); line-height: 1.08; font-weight: 600; }
.process-note p:last-child { margin: 22px 0 0; max-width: 42ch; line-height: 1.75; }

.booking {
  min-height: 82vh;
  padding: clamp(54px, 10vh, 110px) clamp(18px, 6vw, 90px);
  display: grid;
  grid-template-columns: 1.2fr .8fr;
  gap: 8vw;
  align-items: center;
  background: var(--blue);
  color: var(--paper-light);
  border-top: 12px solid var(--red);
}
.booking h2 { margin: 0; max-width: 13ch; font-family: Georgia, "Songti SC", serif; font-size: clamp(42px, 6.4vw, 84px); line-height: 1.02; font-weight: 500; letter-spacing: -.04em; }
.booking-action { max-width: 450px; }
.booking-action p { margin: 0 0 24px; font-size: 17px; line-height: 1.75; }
.booking a { display: flex; align-items: center; justify-content: space-between; min-height: 62px; padding: 15px 20px; color: var(--ink); background: var(--yellow); text-decoration: none; font-size: 17px; font-weight: 900; box-shadow: 7px 7px 0 var(--red); }
.booking small { display: block; margin-top: 20px; opacity: .78; letter-spacing: .08em; }
.webgl-unavailable .hero { grid-template-columns: 1fr 1fr; }

@media (max-width: 760px) {
  .repair-page, .repair-story { min-height: 235vh; }
  .repair-page canvas { top: 220px; height: 48vh; }
  .workshop-header { min-height: 58px; padding: 10px 16px; }
  .workshop-header p { display: none; }
  .hero { min-height: 112vh; padding: 28px 16px 30px; display: block; }
  .hero-copy { padding: 0; }
  h1 { max-width: 11ch; font-size: clamp(38px, 12.4vw, 58px); line-height: 1.01; }
  .intro { max-width: 34ch; margin: 18px 0; font-size: 14px; line-height: 1.6; }
  .fault-picker { gap: 7px; }
  .fault-picker button { min-height: 44px; padding: 8px 11px; font-size: 13px; }
  .diagnostic-card { width: 100%; margin-top: 47vh; padding: 16px; }
  .stage-rail { margin-inline: -16px; }
  .process-note { min-height: 68vh; padding: 12vh 16px; display: block; }
  .process-note > div { margin-top: 20px; padding: 20px 16px; }
  .process-note h2 { font-size: clamp(30px, 9vw, 42px); }
  .booking { min-height: 76vh; padding: 64px 18px; display: block; }
  .booking h2 { max-width: 11ch; font-size: clamp(40px, 12vw, 58px); }
  .booking-action { margin-top: 48px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}
